var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original regex with ^ should match only at the start
    // The new regex without ^ may match in the middle of a string
    // Test with a string that has a +100kb in the middle
    assert.strictEqual(bytes.parse('abc+100kb'), null);
    assert.strictEqual(bytes.parse('abc+100kbxyz'), null);
    // But the original should still match at the start
    assert.strictEqual(bytes.parse('+100kb'), 102400);
  });
});

